const md = $json.profile_md;
if (typeof md !== 'string' || md.trim().length < 20) {
  throw new Error('profile.md could not be loaded or is empty. Check Runtime Settings.profileUrl.');
}
const match = md.match(/```profile-config\s*([\s\S]*?)```/i);
if (!match) throw new Error('profile.md is missing the fenced ```profile-config JSON block.');
let config;
try { config = JSON.parse(match[1]); } catch (e) { throw new Error(`Invalid JSON in profile-config: ${e.message}`); }
const required = ['schema_version','profile_id','enabled','job_source','commercial','scoring','notifications','proposal'];
for (const key of required) if (config[key] === undefined) throw new Error(`profile-config missing required field: ${key}`);
if (config.schema_version !== '1.0') throw new Error(`Unsupported profile schema_version ${config.schema_version}; expected 1.0`);
if (!/^[a-zA-Z0-9._-]+$/.test(config.profile_id)) throw new Error('profile_id may contain only letters, numbers, dot, underscore, and hyphen.');
if (config.enabled !== true) return [];
if (config.job_source?.provider !== 'upwork_graphql') throw new Error('Phase 1 supports job_source.provider = upwork_graphql only.');
if (!Array.isArray(config.job_source?.search_lanes) || !config.job_source.search_lanes.length) throw new Error('At least one job_source.search_lanes entry is required.');
for (const [i,lane] of config.job_source.search_lanes.entries()) {
  if (!lane?.name || !lane?.query) throw new Error(`search_lanes[${i}] requires name and query.`);
}
const dangerousKeys = ['api_key','apikey','access_token','refresh_token','client_secret','password','bot_token','ssh_key'];
const flat = JSON.stringify(config).toLowerCase();
for (const key of dangerousKeys) {
  if (flat.includes(`\"${key}\"`)) throw new Error(`Do not store secrets in profile.md (${key}). Use n8n Credentials.`);
}
const defaults = {
  first_run_behavior: 'seed',
  max_job_age_hours: 24,
  results_per_lane: 10,
  hard_min_hourly: 0,
  hard_min_fixed: 0,
  alert_min_score: 65,
  high_priority_score: 85
};
config.first_run_behavior = ['seed','alert'].includes(config.first_run_behavior) ? config.first_run_behavior : defaults.first_run_behavior;
config.job_source.max_job_age_hours = Number(config.job_source.max_job_age_hours ?? defaults.max_job_age_hours);
config.job_source.results_per_lane = Math.max(1, Math.min(50, Number(config.job_source.results_per_lane ?? defaults.results_per_lane)));
config.commercial.hard_min_hourly = Number(config.commercial.hard_min_hourly ?? defaults.hard_min_hourly);
config.commercial.hard_min_fixed = Number(config.commercial.hard_min_fixed ?? defaults.hard_min_fixed);
config.filters = config.filters || {};
config.filters.blocked_keywords = Array.isArray(config.filters.blocked_keywords) ? config.filters.blocked_keywords.filter(Boolean) : [];
config.scoring.alert_min_score = Number(config.scoring.alert_min_score ?? defaults.alert_min_score);
config.scoring.high_priority_score = Number(config.scoring.high_priority_score ?? defaults.high_priority_score);
return [{json:{profile_id:config.profile_id, display_name:config.display_name || config.profile_id, config, profile_md:md}}];

const p = $('Parse & Validate Profile').first().json;
const state = $input.first().json || {};
const isFirstRun = !state.profile_id;
const query = `query SearchJobs($filter: MarketplaceJobPostingsSearchFilter) {
  marketplaceJobPostingsSearch(
    marketPlaceJobFilter: $filter
    searchType: USER_JOBS_SEARCH
    sortAttributes: [{ field: RECENCY }]
  ) {
    totalCount
    edges {
      node {
        id title description ciphertext duration durationLabel engagement
        amount { displayValue currency }
        experienceLevel category subcategory freelancersToHire enterprise premium totalApplicants applied
        createdDateTime publishedDateTime renewedDateTime
        hourlyBudgetMin { displayValue currency }
        hourlyBudgetMax { displayValue currency }
        skills { name prettyName highlighted }
        client {
          totalHires totalPostedJobs totalSpent { displayValue currency }
          verificationStatus totalReviews totalFeedback
          location { city country timezone }
        }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}`;
return p.config.job_source.search_lanes.map((lane, index) => ({json:{
  profile_id:p.profile_id,
  display_name:p.display_name,
  profile_md:p.profile_md,
  config:p.config,
  is_first_run:isFirstRun,
  first_run_behavior:p.config.first_run_behavior,
  search_lane:{name:lane.name, query:lane.query, weight:Number(lane.weight ?? 1), index},
  graphql_query:query,
  variables:{filter:{searchExpression_eq:lane.query,pagination_eq:{after:'0',first:p.config.job_source.results_per_lane}}}
}}));

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.-]/g,''));
  return Number.isFinite(n) ? n : null;
}
function clean(s){return String(s ?? '').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();}
const responses = $input.all();
const reqs = $('Build Search Requests').all();
const out=[];
for (let i=0;i<responses.length;i++) {
  const res=responses[i].json;
  const req=reqs[i]?.json || reqs[0].json;
  if (Array.isArray(res?.errors) && res.errors.length) {
    throw new Error(`Upwork GraphQL error in lane ${req.search_lane?.name}: ${res.errors.map(e=>e.message).join('; ')}`);
  }
  const edges=res?.data?.marketplaceJobPostingsSearch?.edges || [];
  for (const edge of edges) {
    const j=edge?.node; if (!j?.id) continue;
    const published=j.publishedDateTime || j.createdDateTime || null;
    const ageHours=published ? (Date.now()-new Date(published).getTime())/3600000 : null;
    const hourlyMin=num(j.hourlyBudgetMin?.displayValue);
    const hourlyMax=num(j.hourlyBudgetMax?.displayValue);
    const fixedAmount=num(j.amount?.displayValue);
    const text=`${clean(j.title)} ${clean(j.description)}`.toLowerCase();
    let pass=true, reason='';
    if (ageHours !== null && ageHours > req.config.job_source.max_job_age_hours) {pass=false; reason=`older than ${req.config.job_source.max_job_age_hours}h`;}
    if (pass && hourlyMax !== null && hourlyMax < req.config.commercial.hard_min_hourly) {pass=false; reason=`hourly max ${hourlyMax} below hard floor ${req.config.commercial.hard_min_hourly}`;}
    const looksHourly = hourlyMin !== null || hourlyMax !== null;
    if (pass && !looksHourly && fixedAmount !== null && fixedAmount > 0 && fixedAmount < req.config.commercial.hard_min_fixed) {pass=false; reason=`fixed budget ${fixedAmount} below hard floor ${req.config.commercial.hard_min_fixed}`;}
    if (pass) {
      const blocked=(req.config.filters?.blocked_keywords || []).find(k=>k && text.includes(String(k).toLowerCase()));
      if (blocked) {pass=false; reason=`blocked keyword: ${blocked}`;}
    }
    const ciphertext=j.ciphertext || '';
    out.push({json:{
      dedupe_key:`${req.profile_id}:${j.id}`,
      profile_id:req.profile_id, display_name:req.display_name, profile_md:req.profile_md, config:req.config,
      is_first_run:req.is_first_run, first_run_behavior:req.first_run_behavior,
      search_lane:req.search_lane,
      pre_filter_pass:pass, pre_filter_reason:reason,
      job:{
        id:String(j.id), ciphertext, title:clean(j.title), description:clean(j.description),
        published_at:published, created_at:j.createdDateTime || null, age_hours:ageHours,
        experience_level:j.experienceLevel || null, duration:j.durationLabel || j.duration || null,
        engagement:j.engagement || null, category:j.category || null, subcategory:j.subcategory || null,
        applicants:j.totalApplicants ?? null, enterprise:!!j.enterprise, premium:!!j.premium, applied:!!j.applied,
        skills:(j.skills || []).map(s=>s.prettyName || s.name).filter(Boolean),
        budget:{hourly_min:hourlyMin,hourly_max:hourlyMax,fixed_amount:fixedAmount,currency:j.hourlyBudgetMin?.currency || j.hourlyBudgetMax?.currency || j.amount?.currency || 'USD'},
        client:{total_hires:j.client?.totalHires ?? null,total_posted_jobs:j.client?.totalPostedJobs ?? null,total_spent:j.client?.totalSpent?.displayValue ?? null,verification_status:j.client?.verificationStatus ?? null,total_reviews:j.client?.totalReviews ?? null,total_feedback:j.client?.totalFeedback ?? null,location:j.client?.location || null},
        url:ciphertext ? `https://www.upwork.com/jobs/${ciphertext}` : null
      }
    }});
  }
}
return out;

const map=new Map();
for (const item of $input.all()) {
  const k=item.json.dedupe_key;
  const prev=map.get(k);
  if (!prev || Number(item.json.search_lane?.weight ?? 0) > Number(prev.json.search_lane?.weight ?? 0)) map.set(k,item);
}
return [...map.values()];

const x=$json;
let score=0, decision='deterministic_reject', reason=x.pre_filter_reason || 'rejected by deterministic filter', alerted=false;
if (x.pre_filter_pass && x.is_first_run && x.first_run_behavior==='seed') {score=-1;decision='seeded';reason='first-run seed baseline';}
return [{json:{dedupe_key:x.dedupe_key,profile_id:x.profile_id,job_id:x.job.id,ciphertext:x.job.ciphertext||'',title:x.job.title,published_at:x.job.published_at||new Date().toISOString(),first_seen_at:new Date().toISOString(),score,decision,alerted,search_lane:x.search_lane?.name||'',job_url:x.job.url||'',reason}}];

const x=$json;
const cfg=x.config;
const job=x.job;
const prompt=`You are scoring an Upwork job for a freelancer using the customer-owned profile below.
Do not invent experience. Use only evidence in profile.md and the job payload.
Return the exact structured fields required by the connected output parser.

SCORING POLICY
Alert threshold: ${cfg.scoring.alert_min_score}/100
High priority: ${cfg.scoring.high_priority_score}/100
Weights: ${JSON.stringify(cfg.scoring.weights || {})}
Search lane: ${x.search_lane.name} (weight ${x.search_lane.weight})

Assess technical fit, role/scope fit, commercial fit, client quality, recency/competition, and how credibly a tailored proposal can be written.
Detect any screening instruction such as a required word/phrase and reproduce it exactly in screening_instruction.
proposal_opening must be concise, specific, and within about ${cfg.proposal?.max_opening_words || 120} words. Avoid generic filler and never claim a project/skill not supported by profile.md.

PROFILE.MD
---
${x.profile_md}
---

UPWORK JOB
${JSON.stringify(job,null,2)}

Return score 0-100. decision should be alert, maybe, or reject. match_reason should be one concise sentence.`;
return [{json:{...x,ai_prompt:prompt}}];

const source=$('Build AI Prompt').item.json;
const ai=$json.output ?? $json;
const score=Math.max(0,Math.min(100,Number(ai.score ?? 0)));
const telegramPolicy=source.config.notifications?.telegram || {};
const threshold=Math.max(Number(source.config.scoring.alert_min_score ?? 65), Number(telegramPolicy.min_score ?? 0));
const shouldAlert=telegramPolicy.enabled !== false && score >= threshold;
const priority=score >= Number(source.config.scoring.high_priority_score ?? 85) ? 'high' : (shouldAlert ? 'normal' : 'none');
return [{json:{...source,ai:{...ai,score},should_alert:shouldAlert,priority}}];

function esc(s){return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
const x=$json,j=x.job,a=x.ai;
const age=j.age_hours==null?'unknown':j.age_hours<1?`${Math.max(1,Math.round(j.age_hours*60))}m ago`:j.age_hours<24?`${Math.round(j.age_hours)}h ago`:`${Math.round(j.age_hours/24)}d ago`;
let budget='Budget not specified';
if (j.budget.hourly_min!=null || j.budget.hourly_max!=null) budget=`$${j.budget.hourly_min ?? '?'}–$${j.budget.hourly_max ?? '?'}/hr`;
else if (j.budget.fixed_amount!=null) budget=`Fixed $${j.budget.fixed_amount}`;
const c=j.client||{};
const client=[c.verification_status?`Payment: ${c.verification_status}`:null,c.total_feedback!=null?`${c.total_feedback}★ (${c.total_reviews ?? 0})`:null,c.total_hires!=null?`${c.total_hires} hires`:null,c.total_spent?`${c.total_spent} spent`:null,c.location?.country||null].filter(Boolean).join(' · ') || 'Client details limited';
const risks=(a.risks||[]).slice(0,3).map(r=>`• ${esc(r)}`).join('
') || '• None identified';
const screening=a.screening_instruction?`

<b>Screening instruction:</b> ${esc(a.screening_instruction)}`:'';
const icon=x.priority==='high'?'🔥':'🟢';
const titleUrl=j.url?`<a href="${esc(j.url)}">${esc(j.title)}</a>`:esc(j.title);
const text=`${icon} <b>${a.score}/100 — ${titleUrl}</b>
Posted: ${age} · ${esc(budget)}
Lane: ${esc(x.search_lane.name)}

<b>Why it fits:</b> ${esc(a.match_reason)}

<b>Client:</b> ${esc(client)}

<b>Risks:</b>
${risks}${screening}

<b>Suggested opening:</b>
${esc(a.proposal_opening)}`;
return [{json:{...x,telegram_html:text}}];
